sealed class PaymentFailure implements Exception {
  const PaymentFailure();
}

class CardDeclined extends PaymentFailure {
  final String code;
  const CardDeclined(this.code);
  @override
  String toString() => 'CardDeclined($code)';
}

class NetworkDown extends PaymentFailure {
  const NetworkDown();
}

String describe(PaymentFailure f) => switch (f) {
  CardDeclined(:final code) => 'Card declined ($code)',
  NetworkDown() => 'No connection',
};

Future<void> pay(Order order) async {
  try {
    await gateway.charge(order);
  } on CardDeclined catch (e) {
    showBanner(describe(e));         // expected, recoverable
  } catch (e, stackTrace) {
    logger.error(e, stackTrace);     // keep the stack trace
    rethrow;                          // preserves the ORIGINAL trace
  } finally {
    setLoading(false);                // always runs
  }
}

