        Expanded(
          child: ListView.builder(
            itemCount: _items.length,
            itemBuilder: (_, i) => ItemTile(item: _items[i]),
          ),
        ),
        // Passes data explicitly — rebuilds only when _items changes
        CartTotal(items: _items),
      ],
    );
  }
