  await Isolate.spawn(_worker, receivePort.sendPort);

  receivePort.listen((message) {
    print('Result: $message');
    receivePort.close();
  });
}

// Must be a top-level function
void _worker(SendPort sendPort) {
  var sum = 0;
  for (var i = 0; i < 100000000; i++) sum += i;
  sendPort.send(sum);
}

