class _AppState extends State<App> {
  final _cart = CartNotifier();

  @override
  void dispose() {
    _cart.dispose();                    // ✅ explicit
    super.dispose();
  }

  @override Widget build(BuildContext context) {
    return ListenableProvider<CartNotifier>.value(
      value: _cart,                     // not disposed by provider
      child: const Home(),
    );
  }
}

// ── Coarse state — User has many fields ──
class UserNotifier extends ChangeNotifier {
  String _name = 'Ada';
  int _age = 30;
  String _email = 'a@x.com';
  String get name => _name;
  int get age => _age;
  String get email => _email;
  void setName(String v)  { _name = v;  notifyListeners(); }
  void setAge(int v)      { _age = v;   notifyListeners(); }
  void setEmail(String v) { _email = v; notifyListeners(); }
}

// ❌ Watches whole notifier — rebuilds on age, email, ANY change
class NameLabelBad extends StatelessWidget {
  const NameLabelBad({super.key});
  @override Widget build(BuildContext context) {
    final user = context.watch<UserNotifier>();
    return Text(user.name);
  }
}

// ✅ context.select — rebuilds only when name changes
class NameLabel extends StatelessWidget {
  const NameLabel({super.key});
  @override Widget build(BuildContext context) {
    final name = context.select<UserNotifier, String>((u) => u.name);
    return Text(name);
  }
}

// ✅ Selector — same logic, with child optimization
Selector<UserNotifier, String>(
  selector: (_, u) => u.name,
  builder: (_, name, child) {
    return Row(children: [
      Text(name),
      child!,                     // expensive trailing widget never rebuilds
    ]);
  },
  child: const ExpensiveTrailing(),
);

// ── Selecting a tuple ──
final nameAndAge = context.select<UserNotifier, (String, int)>(
  (u) => (u.name, u.age),
);
// Records have value equality — rebuilds only when name OR age changes

// ── ❌ Selecting a List by reference rebuilds every time ──
final items = context.select<CartNotifier, List<Item>>((c) => c.items);
// If CartNotifier returns a new list (e.g. List.unmodifiable(_items)) on every read,
// the selector sees a different reference each call → constant rebuilds.
//
// ✅ Either return the length, or override == on the list (use IList from
// fast_immutable_collections), or split into focused selectors:
final count = context.select<CartNotifier, int>((c) => c.items.length);

// ── Smell: a giant notifier ──
// If your selectors get gnarly, the notifier is doing too much. Split it:
// AuthNotifier, ProfileNotifier, PreferencesNotifier — each focused.

// ── 1) Compile-time safety ──

// Provider — runtime crash if not wired up
final n = Provider.of<AuthNotifier>(context); // ❌ ProviderNotFoundException

// Riverpod — type-checked, value-based reference
final auth = ref.watch(authProvider);          // ✅ compile-time safe

// ── 2) Reading without context ──

// Provider — service classes can't read it
// class SyncService { void start() { /* no context here */ } }

// Riverpod — ProviderContainer or Ref work without BuildContext
class SyncService {
  final Ref ref;
  SyncService(this.ref);
  void start() {
    final api = ref.read(apiClientProvider);   // ✅ works anywhere
  }
}

// ── 3) AsyncValue — first-class async state ──
final profileProvider = FutureProvider<User>((ref) async => api.me());

// Consumer
ref.watch(profileProvider).when(
  data:    (user) => Text(user.name),
  loading: ()      => const _Spinner(),
  error:   (e, _)  => _Error(error: e),
);
// Provider's FutureProvider doesn't give you this — you'd have to build the three states yourself.

// ── 4) Family — parameterized providers ──
final productProvider = FutureProvider.family<Product, int>(
  (ref, id) => ref.watch(apiProvider).product(id),
);
ref.watch(productProvider(42));                // each id cached separately

// Provider equivalent requires building your own keyed cache by hand.

// ── 5) Testing — pure Dart, no widget tree ──
test('login', () async {
  final container = ProviderContainer(overrides: [
    apiClientProvider.overrideWithValue(FakeApiClient()),
  ]);
  addTearDown(container.dispose);

  await container.read(authProvider.notifier).signIn('a@x.com', 'pwd');
  expect(container.read(authProvider).value?.email, 'a@x.com');
});

// ── Summary in one line ──
// Provider gives you DI through the widget tree.
// Riverpod gives you DI as a typed, reactive graph that happens to render UI.

// Roughly what context.watch<T>() expands to inside the provider package
T watch<T>(BuildContext context) {
  final element = context
      .dependOnInheritedWidgetOfExactType<_InheritedProviderScope<T?>>();
  return element!.value as T;      // dependency registered -> rebuild on notify
}

// read<T>() — same lookup, no dependency, so it is safe outside build()
T read<T>(BuildContext context) {
  final element = context
      .getElementForInheritedWidgetOfExactType<_InheritedProviderScope<T?>>();
  return (element!.widget as dynamic).value as T;
}

// ── Exact-type lookup: the most common wiring bug ──
abstract class AuthNotifier extends ChangeNotifier { void signOut(); }
class AuthNotifierImpl extends AuthNotifier { @override void signOut() {} }

// ❌ registers _InheritedProviderScope<AuthNotifierImpl?>
ChangeNotifierProvider(create: (_) => AuthNotifierImpl());
context.watch<AuthNotifier>();   // ProviderNotFoundException

// ✅ register the type you intend to read
ChangeNotifierProvider<AuthNotifier>(create: (_) => AuthNotifierImpl());

// ── Where watch is legal ──
class Badge extends StatefulWidget {
  const Badge({super.key});
  @override State<Badge> createState() => _BadgeState();
}

class _BadgeState extends State<Badge> {
  @override
  void initState() {
    super.initState();
    context.watch<CartNotifier>();          // ❌ asserts: not building
    final cart = context.read<CartNotifier>(); // ✅ one-off read
    cart.warmUp();
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    context.watch<CartNotifier>();          // ✅ legal here too
  }

  @override
  Widget build(BuildContext context) {
    final count = context.select<CartNotifier, int>((c) => c.count);
    return Text('$count');
  }
}

// ❌ Provider lives inside the page, dialog is built by the Navigator above it
class CartPage extends StatelessWidget {
