// ✅ Capture above, re-expose inside the route
onPressed: () {
  final cart = ctx.read<CartNotifier>();     // read while still in the subtree
  showDialog(
    context: ctx,
    builder: (_) => ChangeNotifierProvider<CartNotifier>.value(
      value: cart,                            // .value — do NOT use create:
      child: const CartDialog(),
