// ── HydratedCubit — the simple case ──
class ThemeCubit extends HydratedCubit<ThemeMode> {
  ThemeCubit() : super(ThemeMode.system);

  void setMode(ThemeMode mode) => emit(mode);

  @override
  ThemeMode? fromJson(Map<String, dynamic> json) {
    final v = json['v'] as int?;
    if (v != 1) return null;                // unknown schema → fall back to initial
    return ThemeMode.values.byName(json['mode'] as String);
  }

  @override
  Map<String, dynamic>? toJson(ThemeMode state) => {
    'v': 1,
    'mode': state.name,
  };
}

// ── HydratedBloc with a complex state ──
@freezed
class DraftState with _$DraftState {
  const factory DraftState({
    required String body,
    required DateTime updatedAt,
  }) = _Draft;
}

class DraftBloc extends HydratedBloc<DraftEvent, DraftState> {
  DraftBloc() : super(DraftState(body: '', updatedAt: DateTime.now())) {
    on<DraftEdited>((e, emit) =>
      emit(state.copyWith(body: e.text, updatedAt: DateTime.now())));
    on<DraftCleared>((_, emit) =>
      emit(DraftState(body: '', updatedAt: DateTime.now())));
  }

  @override
  DraftState? fromJson(Map<String, dynamic> json) {
    try {
      final v = json['v'] as int?;
      if (v != 1) return null;             // ✅ schema migration safety
      return DraftState(
        body: json['body'] as String,
        updatedAt: DateTime.parse(json['updatedAt'] as String),
      );
    } catch (e, s) {
      log('DraftBloc.fromJson: $e');
      return null;
    }
  }

  @override
  Map<String, dynamic>? toJson(DraftState s) => {
    'v': 1,
    'body': s.body,
    'updatedAt': s.updatedAt.toIso8601String(),
  };
}

// ── ❌ Don't persist: stale auth state ──
// class AuthBloc extends HydratedBloc<...> { ... }
// On launch the persisted AuthSuccess(user) is restored, but the actual
// access token may have expired. The user appears signed in until the next
// API call returns 401. Always re-derive auth on launch from a fresh token.

import 'package:bloc_test/bloc_test.dart';
import 'package:mocktail/mocktail.dart';
import 'package:flutter_test/flutter_test.dart';

class MockAuthRepo extends Mock implements AuthRepository {}

void main() {
  late MockAuthRepo repo;

  setUp(() {
    repo = MockAuthRepo();
    registerFallbackValue(const Bootstrap());
  });

  group('AuthBloc', () {
    blocTest<AuthBloc, AuthState>(
      'emits [Loading, Success] when login succeeds',
      setUp: () {
        when(() => repo.login('a@x.com', 'pwd'))
            .thenAnswer((_) async => User(id: 1, email: 'a@x.com'));
      },
      build: () => AuthBloc(repo),
      act: (bloc) => bloc.add(LoginRequested('a@x.com', 'pwd')),
      expect: () => [
        isA<AuthLoading>(),
        isA<AuthSuccess>().having((s) => s.user.email, 'email', 'a@x.com'),
      ],
      verify: (_) => verify(() => repo.login('a@x.com', 'pwd')).called(1),
    );

    blocTest<AuthBloc, AuthState>(
      'emits Failure on bad credentials',
      setUp: () {
        when(() => repo.login(any(), any())).thenThrow(const InvalidCredentials());
      },
      build: () => AuthBloc(repo),
      act: (bloc) => bloc.add(LoginRequested('a@x.com', 'wrong')),
      expect: () => [
        isA<AuthLoading>(),
        isA<AuthFailure>(),
      ],
    );

    blocTest<SearchBloc, SearchState>(
      'debounces and emits Loaded for the latest query',
      build: () => SearchBloc(FakeRepo()),
      act: (bloc) {
        bloc.add(QueryChanged('a'));
        bloc.add(QueryChanged('ab'));
        bloc.add(QueryChanged('abc'));        // only this should fire
      },
      wait: const Duration(milliseconds: 350),
      expect: () => [const Loading(), isA<Loaded>()],
    );
  });

  group('CounterCubit', () {
    blocTest<CounterCubit, int>(
      'emits [1, 2] when increment called twice',
      build: () => CounterCubit(),
      act: (c) { c.increment(); c.increment(); },
      expect: () => [1, 2],
    );

    blocTest<CounterCubit, int>(
      'seeds initial state for tests of mid-flow logic',
      build: () => CounterCubit(),
      seed: () => 10,
      act: (c) => c.increment(),
      expect: () => [11],
    );
  });
}

