enum OrderStatus { pending, shipped, delivered, unknown }

class Order {
  Order({required this.id, required this.status, this.note});

  final String id;
  final OrderStatus status;
  final String? note;              // may become null; never force-unwrap it

  factory Order.fromJson(Map<String, dynamic> json) => Order(
        id: str(json['id']),
        status: OrderStatus.values.firstWhere(
          (s) => s.name == json['status'],
          orElse: () => OrderStatus.unknown,   // ✅ new server value, old app
        ),
        note: json['note'] as String?,
      );
}

// ── Same thing with json_serializable ──
@JsonSerializable()
class OrderDto {
  @JsonKey(unknownEnumValue: OrderStatus.unknown)
  final OrderStatus status;
  @JsonKey(defaultValue: <String>[])
  final List<String> tags;
  OrderDto({required this.status, required this.tags});
}

// ── One place where parsing may fail ──
List<Order> parseOrders(dynamic body) {
  final raw = (body as List).cast<Map<String, dynamic>>();
  final out = <Order>[];
  var dropped = 0;
  for (final json in raw) {
    try {
      out.add(Order.fromJson(json));
    } catch (e, s) {
      dropped++;
      log.warn('order parse failed at id=${json['id']}', e, s);  // redacted
    }
  }
  if (out.isEmpty && raw.isNotEmpty) throw const ContractError('orders');
  if (dropped > 0) metrics.increment('orders.parse_dropped', dropped);
  return out;
}

