final imageCacheManager = CacheManager(Config(
  'images',
  stalePeriod: const Duration(days: 7),
  maxNrOfCacheObjects: 400,
));

// ── Reclaim SQLite pages after a big delete ──
await db.execute('PRAGMA wal_checkpoint(TRUNCATE)');
await db.execute('VACUUM');   // rewrites the file; do it off the hot path

// 1. Ask SQLite what it is doing
final plan = await db.rawQuery(
  'EXPLAIN QUERY PLAN '
  'SELECT * FROM orders WHERE user_id = ? ORDER BY created_at DESC LIMIT 20',
  [userId],
);
// SCAN TABLE orders                     -> no usable index
// SEARCH orders USING INDEX idx_user_created (user_id=?)  -> fixed

// 2. Index that covers the filter AND the sort
await db.execute(
  'CREATE INDEX IF NOT EXISTS idx_user_created ON orders(user_id, created_at DESC)',
);

// 3. ❌ N+1 across the platform channel
for (final order in orders) {
  order.items = await db.query('items', where: 'order_id = ?', whereArgs: [order.id]);
}

// ✅ one query, grouped in Dart
final ids = orders.map((o) => o.id).toList();
final marks = List.filled(ids.length, '?').join(',');
final rows = await db.query('items', where: 'order_id IN ($marks)', whereArgs: ids);
final byOrder = groupBy(rows, (r) => r['order_id']);

// 4. Bulk insert: one transaction, one batch
await db.transaction((txn) async {
  final batch = txn.batch();
  for (final row in incoming) {
    batch.insert('orders', row, conflictAlgorithm: ConflictAlgorithm.replace);
  }
  await batch.commit(noResult: true);
});

// 5. Keyset pagination instead of a growing OFFSET
final page = await db.query('orders',
    where: 'user_id = ? AND created_at < ?', whereArgs: [userId, cursor],
    orderBy: 'created_at DESC', limit: 20);

// 6. One-time setup
await db.execute('PRAGMA journal_mode = WAL');
await db.execute('ANALYZE');

class LogoutService {
  LogoutService(this._api, this._db, this._secure, this._prefs, this._push);

  Future<void> logout() async {
    try {
      await _api.revokeSession();            // best effort, may fail offline
    } catch (_) {}

    await _push.deleteToken();               // stop notifications for this user
    await _secure.deleteAll();               // tokens
    await _db.wipeUserData();                // rows + pending mutation queue
    await _clearUserPrefs();                 // keep theme and locale

    PaintingBinding.instance.imageCache.clear();
    PaintingBinding.instance.imageCache.clearLiveImages();
    await imageCacheManager.emptyCache();    // cached_network_image on disk
    await WebViewCookieManager().clearCookies();
    await FlutterLocalNotificationsPlugin().cancelAll();

    await FirebaseCrashlytics.instance.setUserIdentifier('');
    await analytics.reset();

    await di.resetUserScope();               // drop singletons holding the user
  }

  Future<void> _clearUserPrefs() async {
    for (final key in _prefs.getKeys().where((k) => k.startsWith('user.'))) {
      await _prefs.remove(key);
    }
  }
}

// ── Keychain survives an uninstall on iOS: clear it on first run ──
Future<void> wipeSecureStorageOnFreshInstall(SharedPreferences prefs,
    FlutterSecureStorage secure) async {
  if (prefs.getBool('installed') == true) return;
  await secure.deleteAll();                  // leftovers from a previous install
  await prefs.setBool('installed', true);
}

