  const smiley = '\u{1F600}';              // one emoji, two UTF-16 code units
  const combined = 'é';              // "e" plus a combining acute accent

  print(smiley.length);                    // 2   -> code units
  print(smiley.runes.length);              // 1   -> code points
  print(smiley.characters.length);         // 1   -> user-perceived characters

  print(combined.length);                  // 2
  print(combined.characters.length);       // 1

  print(reverseBroken('ab$smiley'));       // invalid sequence at the front
  print(reverse('ab$smiley'));             // emoji, then "b", then "a"
}

// ── Safe truncation for a bio field ──
String truncate(String s, int max) =>
    s.characters.length <= max ? s : '${s.characters.take(max)}...';

// ── Palindrome over characters, not code units ──
bool isPalindrome(String s) {
  final chars = s.toLowerCase().characters.where((c) => c.trim().isNotEmpty).toList();
  for (var i = 0, j = chars.length - 1; i < j; i++, j--) {
    if (chars[i] != chars[j]) return false;
  }
  return true;
}

// ── FLUTTER SIDE (Dart) ────────────────────────────
class DeviceService {
  static const _method = MethodChannel('com.example.app/device');
  static const _events = EventChannel('com.example.app/accelerometer');

  // One-shot call
  static Future<String> getDeviceId() async {
    try {
      return await _method.invokeMethod<String>('getDeviceId') ?? '';
    } on PlatformException catch (e) {
      throw Exception('Native error: ${e.message}');
    }
  }

  // Calling with arguments
  static Future<bool> vibrate(int duration) async {
    return await _method.invokeMethod<bool>('vibrate', {'duration': duration}) ?? false;
  }

  // Continuous event stream
  static Stream<Map<String, double>> watchAccelerometer() {
    return _events.receiveBroadcastStream().map((event) {
      final m = Map<String, dynamic>.from(event as Map);
      return {'x': m['x'] as double, 'y': m['y'] as double, 'z': m['z'] as double};
    });
  }
}

