// ── Approach 1: trust ONLY your own certificate (strongest) ──
import 'dart:io';
import 'package:dio/io.dart';

Future<Dio> createPinnedDio() async {
  final pem = await rootBundle.load('assets/certs/api_example_com.pem');
  final ctx = SecurityContext(withTrustedRoots: false)
    ..setTrustedCertificatesBytes(pem.buffer.asUint8List());

  final dio = Dio(BaseOptions(baseUrl: 'https://api.example.com'));
  (dio.httpClientAdapter as IOHttpClientAdapter).createHttpClient =
      () => HttpClient(context: ctx);   // every other chain fails the handshake
  return dio;
}

// ── Approach 2: hash comparison, as a second line of defence ──
// Compute the SPKI pin:
//   openssl s_client -connect api.example.com:443 | openssl x509 -pubkey -noout |\
//   openssl pkey -pubin -outform der | openssl dgst -sha256 -binary | base64
const _pins = {
  'primary-pin-base64=',   // current key
  'backup-pin-base64=',    // next key — rotate before the primary expires
};

bool verifyPin(X509Certificate cert) =>
    _pins.contains(base64Encode(sha256.convert(cert.der).bytes));
// NOTE: cert.der is the whole certificate, not the SPKI. Pulling the public key
// out needs an ASN.1 parser (package:asn1lib) or a native pinning library.

// ── ❌ The classic mistake ──
// client.badCertificateCallback = (cert, host, port) => verifyPin(cert);
// It only runs when validation has ALREADY failed. A proxy CA installed on the
// device passes validation, so this line never executes and never blocks it.

// ── Testing ──
// Run through Proxyman/Charles with its CA trusted by the device:
// unpinned build → traffic is readable; pinned build → handshake fails.

// pubspec: flutter_appauth
import 'package:flutter_appauth/flutter_appauth.dart';

final _appAuth = const FlutterAppAuth();
const _clientId = 'mobile-client-id';
const _redirect = 'com.example.app:/oauthredirect';
const _issuer   = 'https://auth.example.com';

Future<TokenSet> signIn() async {
  // flutter_appauth handles PKCE end-to-end:
  // - generates verifier+challenge
  // - opens system browser
  // - exchanges code for tokens
  final result = await _appAuth.authorizeAndExchangeCode(
    AuthorizationTokenRequest(
      _clientId,
      _redirect,
      issuer: _issuer,
      scopes: ['openid', 'profile', 'offline_access'],
      promptValues: const ['login'],
      // ✅ system browser, never WebView
      preferEphemeralSession: true,  // iOS: session not shared with Safari
    ),
  );
  return TokenSet(
    access:  result!.accessToken!,
    refresh: result.refreshToken,
    expiry:  result.accessTokenExpirationDateTime!,
  );
}

// Manual PKCE — when you can't use flutter_appauth
String _generateVerifier() {
  final rand = Random.secure();
  final bytes = List<int>.generate(32, (_) => rand.nextInt(256));
  return base64UrlEncode(bytes).replaceAll('=', '');
}
String _challengeFor(String verifier) =>
    base64UrlEncode(sha256.convert(utf8.encode(verifier)).bytes).replaceAll('=', '');

