// Containment: three steps, in this order
func embed(_ child: UIViewController, in container: UIView) {
  addChild(child)                                    // 1. establish the relationship
  container.addSubview(child.view)                   // 2. install the view
  child.view.translatesAutoresizingMaskIntoConstraints = false
  NSLayoutConstraint.activate([
    child.view.topAnchor.constraint(equalTo: container.topAnchor),
    child.view.leadingAnchor.constraint(equalTo: container.leadingAnchor),
    child.view.trailingAnchor.constraint(equalTo: container.trailingAnchor),
    child.view.bottomAnchor.constraint(equalTo: container.bottomAnchor),
  ])
  child.didMove(toParent: self)                      // 3. tell the child it is installed
}

func unembed(_ child: UIViewController) {
  child.willMove(toParent: nil)
  child.view.removeFromSuperview()
  child.removeFromParent()
}

// Skipping addChild / didMove silently breaks appearance callbacks, trait propagation,
// rotation, and lookups such as child.navigationController.

