@ModelActor
actor ImportActor {
  func importPosts(_ dtos: [PostDTO]) throws -> [PersistentIdentifier] {
    var ids: [PersistentIdentifier] = []
    modelContext.autosaveEnabled = false

    for chunk in dtos.chunked(into: 500) {
      for dto in chunk {
        let post = Post(id: dto.id, title: dto.title)
        modelContext.insert(post)
        ids.append(post.persistentModelID)
      }
      try modelContext.save()          // save per chunk, not per row
    }
    return ids
  }
}

