val deferred = scope.async { failingCall() }
try { deferred.await() } catch (e: Throwable) { /* handle */ }

class SearchViewModel(private val repo: SearchRepo) : ViewModel() {
  private val query = MutableStateFlow("")
  private val onlyInStock = MutableStateFlow(false)

  fun onQueryChange(text: String) { query.value = text }

  @OptIn(FlowPreview::class, ExperimentalCoroutinesApi::class)
  val results: StateFlow<SearchState> =
    combine(query, onlyInStock) { q, inStock -> q to inStock }
      .debounce(300)
      .filter { (q, _) -> q.length >= 2 }
      .distinctUntilChanged()
      .flatMapLatest { (q, inStock) ->        // cancels the previous request
        repo.search(q, inStock)
          .map { SearchState.Results(it) as SearchState }
          .onStart { emit(SearchState.Loading) }
      }
      .catch { emit(SearchState.Error(it)) }
      .stateIn(
        viewModelScope,
        SharingStarted.WhileSubscribed(5_000),
        SearchState.Empty,
      )
}

// zip waits for both sides and pairs them 1:1
val paired = flowOf(1, 2, 3).zip(flowOf("a", "b")) { n, s -> "$n$s" }  // 1a, 2b

// combine re-emits on either side, with the latest of the other
val merged = userFlow.combine(settingsFlow) { user, settings -> render(user, settings) }

// retry only the failures worth retrying
val resilient = repo.search("kotlin")
  .retryWhen { cause, attempt -> cause is IOException && attempt < 3 }

// Default: producer waits for the collector, total time is the sum
flow {
  repeat(3) { emit(load(it)) }        // 100 ms each
}.collect { render(it) }              // 200 ms each  -> ~900 ms

// buffer(): the two run concurrently -> ~600 ms
flow { repeat(3) { emit(load(it)) } }
  .buffer()
  .collect { render(it) }

// conflate(): only the newest value survives a slow collector
sensorReadings
  .conflate()
  .collect { updateGauge(it) }

// collectLatest: cancel the body when a newer value arrives
queries.collectLatest { q ->
  delay(300)                          // cancelled if the user keeps typing
  show(search(q))
}

// flowOn moves the UPSTREAM only
val rows = flow { emit(db.readAll()) }   // runs on IO
  .map { it.toDomain() }                 // runs on IO
  .flowOn(Dispatchers.IO)
  .onEach { render(it) }                 // runs on the collector's context

